"""
Locations of every item pickup.
624 locations across 96 regions.
"""
from typing import Dict, NamedTuple
from BaseClasses import Location

base_id = 41970000


class WildArmsLocation(Location):
    game: str = "Wild Arms"


class LocationData(NamedTuple):
    id: int
    address: int
    mask: int
    region: str
    inverted: bool = False
    prereq_address: int = 0
    prereq_mask: int = 0

# name -> LocationData. id is the offset from base_id; address and mask locate the flag bit that marks the check.
# inverted: the bit starts set and the check is it clearing. prereq_address/prereq_mask (0 = none): a second flag that must be set first.
